-- Demo Google Ads connections ("Try demo" on the Google Ads card, docs/ads-demo.md): whether a
-- connection's figures are generated by bizinsights rather than read from Google, and the seed
-- they are generated from (so the same demo account always shows the same figures).
-- Additive only: code from before ignores both columns.
ALTER TABLE "ad_connections" ADD COLUMN "is_demo" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "ad_connections" ADD COLUMN "demo_seed" INTEGER;
